'use client';

import { useState } from 'react';
import { SectionHeading, Button } from '@/components/ui';

export default function Contact() {
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setStatus('loading');

    const formData = new FormData(e.currentTarget);
    const data = {
      email: formData.get('email'),
      projectType: formData.get('projectType'),
      budget: formData.get('budget'),
      message: formData.get('message'),
    };

    try {
      const response = await fetch('/api/contact', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      });

      if (!response.ok) throw new Error('Failed to send');
      setStatus('success');
    } catch (error) {
      setStatus('error');
    }
  }

  if (status === 'success') {
    return (
      <main className="min-h-screen pt-48 px-6 md:px-12 max-w-3xl mx-auto text-center flex flex-col justify-center h-full">
        <h1 className="font-display text-5xl text-ink mb-6">Transmission Received.</h1>
        <p className="font-sans text-xl text-slate">I will review your brief and respond shortly.</p>
      </main>
    );
  }

  return (
    <main className="min-h-screen pt-48 pb-32 px-6 md:px-12 max-w-3xl mx-auto">
      <SectionHeading>Initiate Launch Sequence</SectionHeading>
      
      <p className="font-sans text-xl text-slate mb-16">
        Describe your project, timeline, and goals. Direct inquiries only.
      </p>

      <form onSubmit={handleSubmit} className="flex flex-col gap-12">
        {/* Email */}
        <div className="flex flex-col gap-4">
          <label htmlFor="email" className="font-mono text-sm uppercase tracking-widest text-slate">Email Address</label>
          <input 
            type="email" 
            id="email" 
            name="email"
            required 
            className="w-full bg-transparent border-b border-hairline pb-4 font-sans text-2xl text-ink focus:outline-none focus:border-signal transition-colors rounded-none"
            placeholder="hello@company.com"
          />
        </div>

        {/* Project Type */}
        <div className="flex flex-col gap-4">
          <label htmlFor="projectType" className="font-mono text-sm uppercase tracking-widest text-slate">Project Type</label>
          <input 
            type="text" 
            id="projectType" 
            name="projectType"
            required 
            className="w-full bg-transparent border-b border-hairline pb-4 font-sans text-2xl text-ink focus:outline-none focus:border-signal transition-colors rounded-none"
            placeholder="e.g. Interactive Web App, 3D Landing Page"
          />
        </div>

        {/* Budget Band */}
        <div className="flex flex-col gap-4">
          <label htmlFor="budget" className="font-mono text-sm uppercase tracking-widest text-slate">Budget Band</label>
          <select 
            id="budget" 
            name="budget"
            required
            className="w-full bg-transparent border-b border-hairline pb-4 font-sans text-2xl text-ink focus:outline-none focus:border-signal transition-colors appearance-none rounded-none cursor-pointer"
          >
            <option value="" disabled selected>Select a range</option>
            <option value="$5k - $10k">$5k - $10k</option>
            <option value="$10k - $25k">$10k - $25k</option>
            <option value="$25k+">$25k+</option>
          </select>
        </div>

        {/* Message */}
        <div className="flex flex-col gap-4">
          <label htmlFor="message" className="font-mono text-sm uppercase tracking-widest text-slate">Project Details</label>
          <textarea 
            id="message" 
            name="message"
            required 
            rows={4}
            className="w-full bg-transparent border-b border-hairline pb-4 font-sans text-xl text-ink focus:outline-none focus:border-signal transition-colors resize-none rounded-none"
            placeholder="Tell me about the problem you are trying to solve..."
          ></textarea>
        </div>

        {status === 'error' && (
          <p className="text-red-600 font-sans">An error occurred while sending. Please try again.</p>
        )}

        <div>
          <button 
            type="submit" 
            disabled={status === 'loading'}
            className="inline-flex items-center justify-center px-8 py-4 font-display font-medium text-lg tracking-tight transition-colors duration-200 text-canvas bg-ink hover:bg-signal rounded-full cursor-pointer disabled:opacity-50"
          >
            {status === 'loading' ? 'Transmitting...' : 'Submit Inquiry'}
          </button>
        </div>
      </form>
    </main>
  );
}
